"""Edge, part B: balancing (L7, L4), the network perimeter (firewalls), network equipment and VPN. The functions l7, l4, firewall, network and vpn exist already."""
from forge import *


def bw():
    """The bandwidth of a link or a gateway, as in the generic VPN / DCI kind."""
    return num("bandwidthMbps", "Пропускная способность", "Bandwidth", unit_="Mbit/s", min=0, group="capacity")


HC_SUB = "health-check {healthCheckSeconds}s"          # the subtitle of a managed balancer


def probe(seconds, threshold, lo=1):
    """The health-check properties of a managed balancer, with the defaults of the service (the engine reads them off every balancer)."""
    return [num("healthCheckSeconds", "Интервал health-check", "Health-check interval", unit_="s", min=lo, default=seconds, group="failover"),
            num("failThreshold", "Порог отказов", "Failure threshold", min=1, default=threshold, group="failover")]


